    #[test]
    fn parse_config_detects_toml_by_extension() {
        let content = "app_name = \"TomlApp\"";
        let config = parse_config(content, Path::new("config.toml")).unwrap();
        assert_eq!(config.app_name, Some("TomlApp".to_string()));
