//! Integration tests for config module public API.

use bivvy::config::{
    load_merged_config, resolve_string, validate, BivvyConfig, InterpolationContext, OutputMode,
};
use std::fs;
use tempfile::TempDir;

#[test]
fn public_api_is_accessible() {
